changeSet.sql:
create or alter procedure [dbo].[GetClaimMappings] @CompanyID int, @url nvarchar(500) as begin set nocount on
declare @ClientID int, @DomainSettingID int, @AuthenticationType int;
select @ClientID = ClientID from Company where ID = @CompanyID;
select @DomainSettingID = DomainSettingID, @AuthenticationType = AuthenticationType from CompanyDomainSetting where CompanyID = @CompanyID and UrlPrefix = @url;
declare @claims table (ClaimType int, [Path] nvarchar(250), IsArray bit, [Action] int)
-- IdP-specific insert into @claims select ClaimType, [Path], IsArray, [Action] from ClaimMapping where ClientID = @ClientID and CompanyID = @CompanyID and DomainSettingID = @DomainSettingID and AuthenticationType = @AuthenticationType
-- Tenant-wide insert into @claims select ClaimType, [Path], IsArray, [Action] from ClaimMapping where ClientID = @ClientID and CompanyID = @CompanyID and DomainSettingID = 0 and AuthenticationType = @AuthenticationType and ClaimType not in (select ClaimType from @claims)
-- Client-wide insert into @claims select ClaimType, [Path], IsArray, [Action] from ClaimMapping where ClientID = @ClientID and CompanyID = 0 and DomainSettingID = 0 and AuthenticationType = @AuthenticationType and ClaimType not in (select ClaimType from @claims)
-- Defaults insert into @claims select ClaimType, [Path], IsArray, [Action] from ClaimMapping where ClientID = 0 and CompanyID = 0 and DomainSettingID = 0 and AuthenticationType = @AuthenticationType and ClaimType not in (select ClaimType from @claims)
select * from @claims end
